//
// NOTE: the GitHub repo is named "visual-saliency-chs" (not
// "visual-salience-chs", the local folder name) - confirm that's the
// intended spelling before this goes live.
const STIMULI_BASE_URL = 'https://github.com/scaffolding-of-cognition-team/visual-saliency-chs/raw/main/stimuli/';

// Subfolder under STIMULI_BASE_URL holding the trial images. Used to be
// per-pair (pair.category was 'BodyParts' or 'Toys'); with body parts
// dropped there is one folder for every trial image. The folder itself is
// still named "Toys" on disk and in the hosted repo - renaming it would
// break the live URLs, so only this pointer would need to change.
const TRIAL_IMAGE_SUBFOLDER = 'Toys';

// Setup-instructions screenshots, self-hosted from this repo's img/ folder
// (see src/text.js) instead of pulling from the separate
// placepath-behavioral repo, so this study doesn't depend on another repo's
// contents staying put.
const IMG_BASE_URL = 'https://github.com/scaffolding-of-cognition-team/visual-saliency-chs/raw/main/img/';

// ---- src/pairs.js ----
// Fixed inventory of the 60 unique image pairs, derived from the same
// within-category factorial as GenerateTrials_Simsom_LWL.m, restricted to
// the objects category (the body-part category has been dropped from this
// study entirely):
//
//   6 object tokens, all unordered token pairs (6 choose 2 = 15),
//   x4 familiarity combinations per token pair (FF, UU, and the two mixed
//     F/U assignments, which are genuinely different images) = 60 pairs.
//
// The MATLAB code gets to its own inventory via a different route: it builds
// *ordered* (target, lure) token pairs x4 familiarity combos, which
// double-count each unordered image pair once per direction (target=A/lure=B
// and target=B/lure=A land on the same two images). Once the spoken label -
// and the target/lure role it created - is dropped, only the unordered pair
// survives, so the objects half of MATLAB's 240 raw slots (120) halves to
// these 60. Same inventory, no label.
//
// 60 pairs is exactly NUM_TRIALS (config.js), so every child sees the
// complete inventory once - see randomization.js.

const TOKENS = ['car', 'ball', 'blocks', 'keys', 'fridge', 'drawer'];

const FAMILIARITIES = ['F', 'U'];

function imageFilename(familiarity, token) {
  return `${familiarity}_${token}.png`;
}

// Canonical pairID: tokenLow-tokenHigh-famOfLowfamOfHigh, tokens sorted
// alphabetically so the ID is stable regardless of trial-time side
// assignment. e.g. "ball-blocks-FU" -> imageA = F_ball.png (the "low"
// token), imageB = U_blocks.png (the "high" token). Side (sideOfA) is
// decided per trial by randomization.js, not baked into the ID.
//
// There is no longer a category segment in the ID (it used to read
// "toys-ball-blocks-FU"): with body parts gone there is only one category,
// so the segment carried no information.
//
// Dash-only (no underscores): pairID gets spliced directly into Lookit
// frame ids (frames.js), and Lookit frame ids may only contain letters,
// numbers, and dashes - an underscore anywhere in one produces a silent
// console-only validation error with no on-screen message.
function getAllPairs() {
  const pairs = [];
  const sortedTokens = [...TOKENS].sort();

  for (let i = 0; i < sortedTokens.length; i++) {
    for (let j = i + 1; j < sortedTokens.length; j++) {
      const tokenLow = sortedTokens[i];
      const tokenHigh = sortedTokens[j];

      for (const famLow of FAMILIARITIES) {
        for (const famHigh of FAMILIARITIES) {
          pairs.push({
            pairID: `${tokenLow}-${tokenHigh}-${famLow}${famHigh}`,
            imageA: imageFilename(famLow, tokenLow),
            imageB: imageFilename(famHigh, tokenHigh),
          });
        }
      }
    }
  }

  return pairs;
}

// ---- src/randomization.js ----
// Seeded trial-set generation.
//
// No global cross-participant state: generateProtocol only ever sees THIS
// session's (child, pastSessions), so there's no participant counter to
// base a rotation/pointer/Latin-square-position on. A seeded PRNG is the
// substitute.
//
// The seed itself is supplied by the caller. protocol.js passes fresh
// entropy per session (see makeSessionSeed there), so every run gets a new
// order; passing a fixed string instead makes the whole session
// reproducible, which is what the checks below and any ad-hoc replay rely
// on. This module is agnostic: same seed in, same session out.
//
// Design translation from GenerateTrials_Simsom_LWL.m (see README for the
// full writeup): the MATLAB script's only real, verified guarantee is
// "every macro-block is a complete, evenly-covered set, shuffled within
// itself for random adjacency" - it does NOT balance side (L/R) at any
// scale, just draws it IID per trial. Now that the inventory is
// objects-only (60 pairs) and the session is 60 trials, one child's session
// IS exactly one such complete macro-block: every pair appears once, in a
// seeded per-child random order. Side assignment mirrors MATLAB exactly:
// IID Bernoulli(0.5) per trial, no forced split.


// Small deterministic PRNG (mulberry32, seeded via xmur3 string hashing).
// Plain public-domain utility pattern - no Math.random() anywhere in this
// file, so a given childId always produces the same session.
function xmur3(str) {
  let h = 1779033703 ^ str.length;
  for (let i = 0; i < str.length; i++) {
    h = Math.imul(h ^ str.charCodeAt(i), 3432918353);
    h = (h << 13) | (h >>> 19);
  }
  return function () {
    h = Math.imul(h ^ (h >>> 16), 2246822507);
    h = Math.imul(h ^ (h >>> 13), 3266489909);
    return (h ^= h >>> 16) >>> 0;
  };
}

function mulberry32(seed) {
  let state = seed;
  return function () {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function createRng(seedString) {
  const seedFn = xmur3(String(seedString));
  return mulberry32(seedFn());
}

function shuffle(array, rng) {
  const result = array.slice();
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}

function pickOne(list, rng) {
  return list[Math.floor(rng() * list.length)];
}

// Shuffled-bag ("deck") sampler: deal a shuffled copy of `items` one at a
// time, reshuffle once the bag is empty. Sampling WITHOUT replacement
// within each bag is what stops the clumping that plain IID draws produce.
//
// Why this replaced pickOne for attention-getter properties: MATLAB's
// `datasample` draws IID with replacement, and with only 5 shapes / 5
// sounds and ~15 AGs in a session, that means a 20% chance that any two
// consecutive AGs share a shape, a 37% chance a session contains the same
// shape three times in a row, and ~2.7 back-to-back same-sound pairs per
// session (simulated over 5000 sessions). Statistically unremarkable,
// visibly repetitive to a parent watching, and an AG that has stopped
// being novel has stopped doing its one job.
//
// avoidImmediateRepeat guards the seam between bags - without it, the last
// item of one bag and the first of the next can still match. Implemented
// by swapping the offending first element with a random later one, which
// is cheaper than reshuffling until it passes and keeps every item
// reachable. Left OFF for `side`, where 2 items + no repeats would force
// strict L/R/L/R alternation: perfectly predictable AG locations are worse
// for a frame whose purpose is a known-gaze-direction reference than the
// occasional repeated side.
//
// Marginal frequencies stay uniform; what changes is the spacing. Each
// shape/sound now appears ~3 times per session and each motion ~5, spread
// out rather than clumped.
function makeBagSampler(items, rng, options = {}) {
  const avoidImmediateRepeat = options.avoidImmediateRepeat !== false;
  let bag = [];
  let last = null;

  return function draw() {
    if (bag.length === 0) {
      bag = shuffle(items, rng);
      if (avoidImmediateRepeat && items.length > 1 && bag[0] === last) {
        const swapWith = 1 + Math.floor(rng() * (bag.length - 1));
        [bag[0], bag[swapWith]] = [bag[swapWith], bag[0]];
      }
    }
    last = bag.shift();
    return last;
  };
}

// One sampler per factor, so shape / sound / motion / side each cycle
// independently - the factorial (5 x 5 x 3 x 2 = 150 combinations) is
// preserved, and two AGs sharing a shape will still differ in sound and
// motion.
//
// Draw ORDER is unchanged from the MATLAB original (is_AG_right =
// randi([0,1]), then datasample over shapes, sounds, motions); the draw
// COUNT is not, since a reshuffle consumes extra rng values. That only
// affects sessionRng, which nothing else depends on - childRng, and so
// every image trial, is untouched (see the two-stream note below).
function makeAttentionGetterSampler(rng) {
  const drawSide = makeBagSampler(['left', 'right'], rng, { avoidImmediateRepeat: false });
  const drawShape = makeBagSampler(AG_SHAPES, rng);
  const drawSound = makeBagSampler(AG_SOUNDS, rng);
  const drawMotion = makeBagSampler(AG_MOTIONS, rng);

  return function buildAttentionGetter() {
    return {
      side: drawSide(),
      shape: drawShape(),
      sound: drawSound(),
      motion: drawMotion(),
    };
  };
}

// Returns an ordered array of trial-unit plans:
//   { pairID, imageA, imageB, sideOfA, attentionGetter, isiSeconds }
// Exactly one of attentionGetter / isiSeconds is non-null per trial: an AG
// replaces the ISI (MATLAB's Post_wait covers that gap instead).
// TWO INDEPENDENT RNG STREAMS, and the split is deliberate:
//
//   childRng   - pair order, side assignment, ISI durations. Seeded from
//                the child's identity, so the image trials are IDENTICAL
//                every time this runs for that child. A reload therefore
//                does NOT reshuffle them and complete 60-pair coverage
//                survives.
//   sessionRng - whether an AG fires on each trial, and each AG's
//                shape/motion/sound/side. Seeded from fresh per-session
//                entropy, so attention getters vary run to run.
//
// They must be separate streams, not one: the number of draws an AG
// consumes varies (0 when it doesn't fire, 5 when it does), so a single
// stream would let the AG schedule shift every downstream image draw - the
// exact coupling this split exists to break. Each stream's consumption is
// now independent of the other's.
function generateSessionPlan(seeds, allPairs, options = {}) {
  const numTrials = options.numTrials || NUM_TRIALS;
  const isiRange = options.isiRange || ISI_SECONDS_RANGE;

  // A bare string is accepted so a single seed still reproduces a whole
  // session (used for replaying a session by hand, and by the checks).
  const { childSeed, sessionSeed } =
    typeof seeds === 'string' ? { childSeed: seeds, sessionSeed: seeds } : seeds;

  if (allPairs.length < numTrials) {
    throw new Error(`Only ${allPairs.length} pairs available, need ${numTrials}`);
  }
  if (!childSeed || !sessionSeed) {
    throw new Error('generateSessionPlan needs both childSeed and sessionSeed');
  }

  const childRng = createRng(childSeed);
  const sessionRng = createRng(sessionSeed);
  const buildAttentionGetter = makeAttentionGetterSampler(sessionRng);

  // Seeded permutation of the whole pair inventory, take the first N. With
  // numTrials === allPairs.length (60 = 60, the intended configuration)
  // the slice is a no-op and this is complete coverage: every child sees
  // every pair exactly once, only the order and side assignment differ
  // between children. That is the full-shuffle-within-a-complete-block step
  // GenerateTrials_Simsom_LWL.m does, now at the level of a single session.
  // The slice is kept so a smaller numTrials (e.g. for a pilot) still
  // yields a uniform random subset rather than throwing.
  const chosenPairs = shuffle(allPairs, childRng).slice(0, numTrials);

  let trialsSinceLastAG = 0;
  const plan = [];

  for (let i = 0; i < numTrials; i++) {
    const pair = chosenPairs[i];
    const isFirstTrial = i === 0;

    trialsSinceLastAG += 1;
    const gapIndex = Math.min(trialsSinceLastAG, AG_PROBABILITY_BY_GAP.length) - 1;
    const agProbability = AG_PROBABILITY_BY_GAP[gapIndex];

    // isFirstTrial short-circuits before drawing - mirrors
    // Experiment_Simsom_LWL.m always forcing an AG on the very first trial
    // (Data.AG_session_counter starts empty), rather than rolling for it.
    const showAG = isFirstTrial || sessionRng() < agProbability;

    let attentionGetter = null;
    if (showAG) {
      attentionGetter = buildAttentionGetter();
      trialsSinceLastAG = 0;
    }

    const sideOfA = childRng() < 0.5 ? 'left' : 'right';

    // Continuous uniform draw on [1, 2) seconds, independently per trial -
    // matches Experiment_Simsom_LWL.m's Parameters.ISI = [1, 2]. Rounded to
    // the millisecond because this value goes straight into the frame's
    // durationSeconds (and into the exported data), where 16 significant
    // digits of a float are noise: the browser's own timer resolution is
    // coarser than that.
    //
    // Drawn unconditionally from childRng, then discarded on
    // attention-getter trials, where the AG's own Post_wait stands in for
    // the ISI (see frames.js's buildTrialGroup). Drawing first and
    // discarding after keeps exactly one childRng draw per trial, so the
    // image-trial stream stays independent of which trials the session's
    // AG schedule happens to land on.
    const isiDraw =
      Math.round((isiRange[0] + childRng() * (isiRange[1] - isiRange[0])) * 1000) / 1000;
    const isiSeconds = attentionGetter ? null : isiDraw;

    plan.push({
      pairID: pair.pairID,
      imageA: pair.imageA,
      imageB: pair.imageB,
      sideOfA,
      attentionGetter,
      isiSeconds,
    });
  }

  return plan;
}

// ---- src/frames.js ----
// Turns a per-child session plan (src/randomization.js) into actual EFP
// frame objects.
//
// Frame-kind choices, confirmed against the live Lookit Ember Frameplayer
// docs (lookit.readthedocs.io/projects/frameplayer) before writing this:
//
// - exp-lookit-images-audio: test trials AND the blank inter-trial
//   interval (empty images array). Per your decision, images only, no
//   trial audio, duration driven by durationSeconds. Positioning uses
//   images[].left/width/top/height (percentages), NOT the position:
//   'left'/'right' preset - those presets don't reproduce MATLAB's actual
//   spacing (see TRIAL_IMAGE_* constants in config.js, derived from
//   Experiment_Simsom_LWL.m's ImageSize/eccentricity).
//
// - exp-lookit-calibration: doubles as the attention-getter. Its whole
//   documented purpose is "video of the child looking to known locations
//   at known times" - exactly the validation reference iCatcher+/human
//   coding needs, and exactly what you confirmed (AG-as-validation-frame,
//   no separate calibration frame). calibrationPositions is set to
//   [side, 'center'] rather than the default 4-position sweep: one
//   known-side segment (the reference) + one recentering segment before
//   the next trial's images appear, at calibrationLength=3000ms each -
//   2 segments x 3s = 6s total, in the same ballpark as MATLAB's ~6-7s AG.
//   calibrationImageAnimation ('spin'/'bounce') is EFP's built-in
//   replacement for MATLAB's rotate/scale motions; 'orbit' has no
//   equivalent and is dropped (see config.js).
//
// - group + commonFrameProperties: bundles each trial's optional AG + ISI
//   + test-image into one frame. This is the same pattern your own
//   reference protocol uses (test-trial-one..eight), not something
//   invented here.
//
// RECORDING: one session-level recorder spanning the whole trial block
// (exp-lookit-start-recording before trial 1, exp-lookit-stop-recording
// after trial 60), NOT the per-frame doRecording bracket this file used
// to have. That change is what makes the stimulus timing exact, and the
// reason is in the frameplayer's own source:
//
// - At frame start, exp-lookit-images-audio's startTrialIfReady() gates on
//   `(recordingStarted || !recordingNeeded) && image_loaded_count >= nImages`,
//   and only then does startTrial() arm the durationSeconds timer. With
//   per-frame doRecording:true, "stimuli are not displayed and audio is not
//   started until recording begins" (their docs), so every trial paid a
//   webcam spin-up before its images appeared - and because the preceding
//   ISI frame had already rendered a blank gray screen, that spin-up was
//   visually indistinguishable from the ISI. That is why the ISI looked
//   longer than the 1-2s it was actually set to.
// - At frame end, the video-record mixin's willDestroyElement calls
//   stopRecorder() and waits on a promise that "resolves when upload is
//   complete" before the frame advances. showWaitForUploadMessage:false
//   (which we had set, to keep a "please wait" card away from the child)
//   suppresses the cover overlay but NOT the wait - so the two trial
//   images stayed on screen for 6s PLUS a variable, network-dependent
//   stop/upload tail. That is why trials were not exactly 6 seconds.
//
// With doRecording:false on every frame below, the only remaining gate is
// image_loaded_count, so trial images display for exactly
// TRIAL_IMAGE_SECONDS and the ISI lasts exactly its drawn duration.
//
// Tradeoff, stated plainly: a hard crash or tab-close mid-block now risks
// the whole block's video rather than just the trial in progress. A
// graceful Escape -> Exit still runs to the stop-recording frame and
// uploads. Reverting is a small, local change - see README.
//
// Stimuli are hosted at their real MATLAB-mirroring layout
// (stimuli/{AG_stimuli,Toys}/...), not a flat img/ folder, so every
// image/audio `src` below is a full absolute URL built
// from STIMULI_BASE_URL + the real subfolder - this sidesteps EFP's
// baseDir + img//mp3/ auto-subfolder convention entirely rather than
// depending on unverified behavior for a layout it doesn't match anyway.


function oppositeSide(side) {
  return side === 'left' ? 'right' : 'left';
}

function stimulusUrl(subfolder, filename) {
  return `${STIMULI_BASE_URL}${subfolder}/${filename}`;
}

// One exp-lookit-video frame per attention getter, playing a pre-rendered
// clip that reproduces MATLAB's AG_event_sequence (see AG_VIDEO_SECONDS in
// config.js for the beat-by-beat timeline, and scripts/make_ag_assets.py
// for the animation maths).
//
// exp-lookit-calibration cannot express this: it hardcodes the image to
// `width: 12%` / `max-height: 300px`, ships only 'spin' and 'bounce'
// keyframes, and swaps `margin-left` between three fixed positions with no
// CSS transition, so it hard-cuts rather than slides. MATLAB's AG is the
// size of a trial image, sits at a trial image's position, and eases to
// centre on a sigmoid - hence pre-rendered video.
//
// Video carries shape x motion x side (30 clips); the sound rides along as
// a separate `audio` track (5 clips) so it stays an independent factor.
// Both `video/source` and `audio/source` are in the frame's
// assetsToExpand lists, so the [{src, type}] form takes absolute URLs -
// necessary here, since nothing in this study uses baseDir.
function buildAttentionGetterFrame(attentionGetter) {
  const { shape, motion, side, sound } = attentionGetter;
  const videoUrl = stimulusUrl(AG_VIDEO_SUBFOLDER, `ag-${shape}-${motion}-${side}.mp4`);
  const audioUrl = stimulusUrl(AG_VIDEO_SUBFOLDER, `ag-sound-${sound}.mp3`);

  return {
    // Shape/motion/side/sound are all recoverable from the frame id, the
    // same way pairID is on trial frames.
    id: `attention-getter-${shape}-${motion}-${side}-${sound}`,
    kind: 'exp-lookit-video',
    video: {
      source: [{ src: videoUrl, type: 'video/mp4' }],
      // 'fill' scales the clip up preserving aspect ratio. The clip is
      // 16:9 on the same rgb(50,50,50) background as the frame, so any
      // letterboxing on a differently-shaped viewport is invisible.
      position: 'fill',
      loop: false,
    },
    audio: {
      source: [{ src: audioUrl, type: 'audio/mp3' }],
      loop: false,
    },
    // Advance on the video finishing once (it is exactly AG_VIDEO_SECONDS
    // long, Post_wait included). The audio track is the same length and is
    // deliberately NOT a gate - requireAudioCount 0 - so a slow-loading
    // sound can never hold the trial block up.
    requireVideoCount: 1,
    requireAudioCount: 0,
    autoProceed: true,
    backgroundColor: BACKGROUND_COLOR,
    // false: the session recorder installed by the start-recording frame
    // is already running. See the RECORDING note at the top of this file.
    doRecording: false,
  };
}

// Brackets the trial block with one session-level recorder. These are the
// only two frames in the block whose duration is network-dependent, and
// they sit outside every measured trial.
//
// Deliberately NO `image`/`video` placeholder. An earlier version showed a
// spinning AG shape here to give the child something to look at, but it
// reads as a stray, half-second attention getter immediately before the
// real ones - confusing, and it pre-empts the first AG.
//
// `waitForVideoMessage` must also be a NON-EMPTY string. The frame's
// template is `{{#if waitForVideoMessage}} ... {{else}} establishing video
// connection / please wait... {{/if}}`, and '' is falsy in Handlebars, so
// passing an empty string does not blank the text - it shows the built-in
// default instead. Same trap on the stop frame's waitForUploadMessage.
function buildStartRecordingFrame() {
  return {
    id: 'start-session-recording',
    kind: 'exp-lookit-start-recording',
    backgroundColor: BACKGROUND_COLOR,
    displayFullscreen: true,
    waitForVideoMessage: 'Getting the study ready, please wait...',
  };
}

function buildStopRecordingFrame() {
  return {
    id: 'stop-session-recording',
    kind: 'exp-lookit-stop-recording',
    backgroundColor: BACKGROUND_COLOR,
    displayFullscreen: true,
    sessionMaxUploadSeconds: SESSION_MAX_UPLOAD_SECONDS,
    // The child is done by this point, so an upload progress bar is
    // useful to the parent rather than a distraction.
    showProgressBar: true,
    waitForUploadMessage: 'Uploading your video, please do not close this window...',
  };
}

function buildIsiFrame(isiSeconds) {
  return {
    id: 'isi',
    images: [],
    durationSeconds: isiSeconds,
    autoProceed: true,
    doRecording: false,
  };
}

function buildTrialImageFrame(trial) {
  const sideOfB = oppositeSide(trial.sideOfA);
  // Same left offset for both slots - whichever side each image is on
  // determines which offset it gets, not a separate "left slot"/"right
  // slot" pair of constants.
  const leftOffsetBySide = { left: TRIAL_IMAGE_LEFT_MARGIN_PERCENT, right: TRIAL_IMAGE_RIGHT_LEFT_PERCENT };

  return {
    id: `trial-${trial.pairID}`,
    images: [
      {
        id: 'imageA',
        src: stimulusUrl(TRIAL_IMAGE_SUBFOLDER, trial.imageA),
        left: leftOffsetBySide[trial.sideOfA],
        width: TRIAL_IMAGE_WIDTH_PERCENT,
        top: TRIAL_IMAGE_TOP_PERCENT,
        height: TRIAL_IMAGE_HEIGHT_PERCENT,
      },
      {
        id: 'imageB',
        src: stimulusUrl(TRIAL_IMAGE_SUBFOLDER, trial.imageB),
        left: leftOffsetBySide[sideOfB],
        width: TRIAL_IMAGE_WIDTH_PERCENT,
        top: TRIAL_IMAGE_TOP_PERCENT,
        height: TRIAL_IMAGE_HEIGHT_PERCENT,
      },
    ],
    durationSeconds: TRIAL_IMAGE_SECONDS,
    autoProceed: true,
    choiceAllowed: false,
    // false: the session recorder is already running, so nothing gates
    // the images except their own load, and durationSeconds is therefore
    // the exact on-screen time. See the RECORDING note at the top.
    doRecording: false,
    // pairID/sideOfA are carried in the frame id and image ids so they're
    // recoverable from exported session data without a side channel.
  };
}

function buildTrialGroup(trial, index) {
  const frameList = [];

  // An attention getter REPLACES the ISI rather than preceding it, matching
  // the MATLAB script: its AG block ends with `pause(Post_AG_wait)` (0.25s,
  // baked into the tail of every AG clip) and then the trial starts
  // immediately. Only trials with no AG get the 1-2s blank ISI.
  if (trial.attentionGetter) {
    frameList.push(buildAttentionGetterFrame(trial.attentionGetter));
  } else {
    frameList.push(buildIsiFrame(trial.isiSeconds));
  }

  frameList.push(buildTrialImageFrame(trial));

  return {
    id: `trial-group-${index}-${trial.pairID}`,
    frame: {
      kind: 'group',
      frameList,
      // No baseDir/audioTypes here - every src above is already a full
      // absolute URL, so there's nothing for a relative-path convention
      // to resolve.
      commonFrameProperties: {
        kind: 'exp-lookit-images-audio',
        backgroundColor: BACKGROUND_COLOR,
        // pageColor (the actual image-display area, distinct from the
        // outer backgroundColor margin) defaults to white if unset - that
        // default is what was showing through as the white trial
        // background.
        pageColor: BACKGROUND_COLOR,
        autoProceed: true,
        showProgressBar: false,
        showCursor: false,
        // MUST be set explicitly. The pause-unpause mixin defaults this to
        // true, but exp-lookit-images-audio overrides it back to false as a
        // component default (`pauseWhenExitingFullscreen: false, //
        // pause-unpause mixin`), so every image trial and every ISI frame
        // silently ran on through a fullscreen exit. exp-lookit-video (the
        // attention getters) does NOT override it, so AG frames were
        // already pausing - which is why the behaviour looked intermittent
        // rather than absent.
        //
        // This also fixes the Escape key. exp-player's keydown handler
        // calls exitFullscreen() and then showConfirmationDialog() (the
        // Continue/Exit box in the corner that the study copy describes),
        // but with no pause the trials kept advancing behind that dialog
        // while the parent decided. Now the exit-fullscreen half of that
        // handler pauses the trial too.
        pauseWhenExitingFullscreen: true,
        // Default pause cover is WHITE - a full-screen white flash in a
        // dim-background infant study, mid-trial. Matching the study
        // background keeps the pause visually quiet; the mixin picks the
        // pause text colour for contrast itself (textColorForBackground),
        // so dark here is safe.
        pauseColor: BACKGROUND_COLOR,
      },
    },
  };
}

// Returns { frames, sequence } fragments for the trial portion only - the
// caller (protocol.js) merges these into the full study frames/sequence
// alongside the intro/consent/outro frames. The fragment is bracketed by
// the session-recording start/stop frames, so the recorder covers every
// trial and nothing else.
function buildTrialFrames(plan) {
  const startFrame = buildStartRecordingFrame();
  const stopFrame = buildStopRecordingFrame();

  const frames = { [startFrame.id]: startFrame };
  const sequence = [startFrame.id];

  plan.forEach((trial, index) => {
    const { id, frame } = buildTrialGroup(trial, index);
    frames[id] = frame;
    sequence.push(id);
  });

  frames[stopFrame.id] = stopFrame;
  sequence.push(stopFrame.id);

  return { frames, sequence };
}

